const button = document.querySelector('#counter');
let count = 0;
button.addEventListener('click', () => { count += 1; button.textContent = `Count: ${count}`; });

import { cp, mkdir } from 'node:fs/promises';
await mkdir('dist/src', { recursive: true });
await cp('index.html', 'dist/index.html');
await cp('src/app.js', 'dist/src/app.js');
console.log('Built dist/');

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
const routes = new Map([['/', ['index.html', 'text/html']], ['/src/app.js', ['src/app.js', 'text/javascript']]]);
const server = createServer(async (req, res) => {
 const route = routes.get((req.url ?? '/').split('?')[0]);
 if (!route) { res.writeHead(404).end('Not found'); return; }
 try { const bytes = await readFile(route[0]); res.writeHead(200, { 'Content-Type': route[1] + '; charset=utf-8', 'X-Content-Type-Options': 'nosniff' }); res.end(bytes); }
 catch { res.writeHead(500).end('Unable to read application'); }
});
server.listen(4173, '127.0.0.1', () => console.log('Preview: http://127.0.0.1:4173'));
for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => server.close());

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
test('application has an accessible native button and local module', async () => {
 const html = await readFile('index.html', 'utf8');
 assert.match(html, /<button type="button"/);
 assert.match(html, /src=".\/src\/app.js"/);
});
